<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {api,fmt,json} from '@/lib/api';import PageHeader from '@/components/PageHeader.vue';import AppModal from '@/components/AppModal.vue';import EmptyState from '@/components/EmptyState.vue';import {Plus} from 'lucide-vue-next';const items=ref<any[]>([]),products=ref<any[]>([]),open=ref(false),editing=ref<any>(),mappingSite=ref<any>(),form=reactive<any>({}),mapForm=reactive<any>({productId:'',externalName:'',variationName:''});async function load(){[items.value,products.value]=await Promise.all([api('/sites'),api('/products')])}function show(x?:any){editing.value=x;Object.assign(form,x||{name:'',shop:'',currency:'MYR',exchangeRate:1,platformFeeRate:0,active:true});open.value=true}async function save(){await api(editing.value?`/sites/${editing.value.id}`:'/sites',json(editing.value?'PATCH':'POST',form));open.value=false;load()}async function del(x:any){if(confirm('确定删除该站点？存在关联数据时无法删除。'))try{await api(`/sites/${x.id}`,{method:'DELETE'});load()}catch(e:any){alert(e.message)}}function showMappings(x:any){mappingSite.value=x;Object.assign(mapForm,{productId:products.value[0]?.id,externalName:'',variationName:''})}async function addMapping(){await api(`/sites/${mappingSite.value.id}/mappings`,json('POST',mapForm));await load();mappingSite.value=items.value.find(x=>x.id===mappingSite.value.id)}async function removeMapping(id:number){await api(`/sites/mappings/${id}`,{method:'DELETE'});await load();mappingSite.value=items.value.find(x=>x.id===mappingSite.value.id)}onMounted(load)</script>
<template><PageHeader title="站点管理" subtitle="汇率与平台费率会在订单创建时保存历史快照"><el-button type="primary" :icon="Plus" @click="show()">新增站点</el-button></PageHeader><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><el-card v-for="x in items" :key="x.id" shadow="never"><div class="flex justify-between"><div><h3 class="font-bold">{{x.name}}</h3><div class="text-sm text-slate-500">{{x.shop}}</div></div><el-tag :type="x.active?'success':'info'" effect="light">{{x.active?'启用':'停用'}}</el-tag></div><el-descriptions :column="3" direction="vertical" class="my-5" border><el-descriptions-item label="币种">{{x.currency}}</el-descriptions-item><el-descriptions-item label="汇率">{{fmt(x.exchangeRate,4)}}</el-descriptions-item><el-descriptions-item label="平台费率">{{fmt(Number(x.platformFeeRate)*100)}}%</el-descriptions-item></el-descriptions><el-button link type="primary" @click="show(x)">编辑</el-button><el-button link @click="showMappings(x)">商品映射 ({{x.mappings.length}})</el-button><el-button link type="danger" @click="del(x)">删除</el-button></el-card></div><el-empty v-if="!items.length" description="暂无站点"/><AppModal :open="open" :title="editing?'编辑站点':'新增站点'" @close="open=false"><el-form :model="form" label-position="top" @submit.prevent="save"><div class="grid gap-x-4 sm:grid-cols-2"><el-form-item label="站点名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="店铺" required><el-input v-model="form.shop"/></el-form-item><el-form-item label="币种" required><el-input v-model="form.currency" maxlength="3"/></el-form-item><el-form-item label="汇率（1 原币 = CNY）"><el-input-number v-model="form.exchangeRate" :min="0" :precision="6" class="!w-full" controls-position="right"/></el-form-item><el-form-item label="平台费率（小数）"><el-input-number v-model="form.platformFeeRate" :min="0" :precision="6" class="!w-full" controls-position="right"/></el-form-item><el-form-item label="启用状态"><el-switch v-model="form.active" active-text="启用" inactive-text="停用"/></el-form-item></div><div class="flex justify-end gap-2"><el-button @click="open=false">取消</el-button><el-button type="primary" native-type="submit">保存</el-button></div></el-form></AppModal><AppModal :open="!!mappingSite" :title="`${mappingSite?.name||''} · 商品映射`" width="760px" @close="mappingSite=null"><el-form :model="mapForm" label-position="top" @submit.prevent="addMapping"><div class="grid gap-x-3 sm:grid-cols-4"><el-form-item label="内部商品"><el-select v-model="mapForm.productId" filterable class="w-full"><el-option v-for="p in products" :key="p.id" :label="`${p.name} · ${p.sku}`" :value="p.id"/></el-select></el-form-item><el-form-item label="站点商品名称" class="sm:col-span-2"><el-input v-model="mapForm.externalName"/></el-form-item><el-form-item label="Variation"><el-input v-model="mapForm.variationName"/></el-form-item></div><el-button type="primary" native-type="submit">添加映射</el-button></el-form><el-table :data="mappingSite?.mappings||[]" stripe class="mt-5"><el-table-column label="内部 SKU" prop="product.sku"/><el-table-column label="站点商品名称" prop="externalName"/><el-table-column label="规格"><template #default="{row}">{{row.variationName||'—'}}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="danger" @click="removeMapping(row.id)">删除</el-button></template></el-table-column></el-table></AppModal></template>
